// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address depositor, uint112 amount) public {
        vm.assume(depositor != address(0));
        vm.assume(amount > 0);
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.addToBalance{value: amount}();
        uint256 reported = c.getBalance(depositor);
        assertTrue(reported == amount);
    }
}
